import java.util.*;
class Solution {
    public int rob(int[] nums) {
        int twoBack = 0, oneBack = 0;
        for (int amount : nums) {
            int best = Math.max(oneBack, twoBack + amount);
            twoBack = oneBack;
            oneBack = best;
        }
        return oneBack;
    }
}

