class Solution:
    def countPrimes(self, n: int) -> int:
        if n <= 2:
            return 0
        is_prime = bytearray([1]) * n
        is_prime[0:2] = bytes([0, 0])
        for p in range(2, int((n - 1) ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                count = (n - 1 - start) // p + 1
                is_prime[start:n:p] = bytes(count)
        return sum(is_prime)

import java.util.*;
class Solution {
    public int countPrimes(int n) {
        if (n <= 2) return 0;
        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        for (int p = 2; p * p < n; p++) {
            if (isPrime[p]) {
                for (int multiple = p * p; multiple < n; multiple += p) isPrime[multiple] = false;
            }
        }
        int count = 0;
        for (boolean prime : isPrime) if (prime) count++;
        return count;
    }
}

