import java.util.*;
class Solution {
    public boolean isIsomorphic(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] sourceToTarget = new int[Character.MAX_VALUE + 1];
        int[] targetToSource = new int[Character.MAX_VALUE + 1];
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (sourceToTarget[a] != targetToSource[b]) return false;
            sourceToTarget[a] = i + 1;
            targetToSource[b] = i + 1;
        }
        return true;
    }
}

