        previous = None
        current = head
        while current:
            following = current.next
            current.next = previous
            previous, current = current, following
        return previous

import java.util.*;
class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode previous = null, current = head;
        while (current != null) {
            ListNode following = current.next;
            current.next = previous;
            previous = current;
            current = following;
        }
        return previous;
    }
}
